/* =================== конспект, части I–III =================== */
(function(){
const K=BV.K,VZ=BV.VZ,F=BV.EL.FIG,{R,OK,HY,PHIL,PH,PH2,VID}=BV.QSH;
VZ.doc('qs',{kick:'Конспект · Микробиология · элитная группа',title:'Микробная экология и кворум-сенсинг',
 lead:'Кто с кем живёт в микробном сообществе, за что конкурирует, как бактерии договариваются химическими сигналами и из каких метаболитов эти сигналы сделаны. Материал методического конспекта элитной группы, дополненный разделом о метаболизме сигналов.',
 intro:`<div class="k-goal"><b>Как читать</b><ul><li>Идите по порядку: каждый раздел опирается на предыдущие, термины расшифрованы при первом упоминании.</li><li>Рамки «Определение» стоит выучить, в «Ловушках» собраны места, где чаще путаются.</li><li>Метки: ${OK} — есть в статье или монографии, ссылка рядом; ${HY} — вывод, которого нет в источниках в явном виде, или открытый вопрос.</li><li>Номер в квадратных скобках открывает источник. Все расчётные примеры с числами учебные: ссылаться на них как на данные нельзя.</li></ul></div>`,
 end:'Дальше: лаборатория этого раздела с пятью моделями, вузовские задачи по теме в банке задач и колоды «Микробная экология и сигналы» в «Карточках».'});

/* ---- 1. Микробиоценоз и ниша ---- */
VZ.sec('qs',{id:'eco',no:1,t:'Микробиоценоз, ниша и конкуренция',sub:[['k-qs1a','Уровни организации'],['k-qs1b','Состав сообщества'],['k-qs1c','Ниша и принцип Гаузе'],['k-qs1d','Уравнение Моно и хемостат']],kw:['микробиоценоз','биотоп','ниша','конкурентн','гаузе','хемостат','моно','шеннон'],html:()=>`
 <p class="k-lead">Прежде чем разбирать, как бактерии «разговаривают», нужен язык экологии: кто с кем живёт, за что соревнуется и как меняется численность.</p>
 <h3 id="k-qs1a">Уровни организации</h3>
 ${K.tbl(['Уровень','Определение','Пример'],[['Особь (клетка)','отдельная клетка; у бактерий она же организм','одна клетка Bacillus subtilis'],['Популяция','особи одного вида в одном месте и времени, способные обмениваться генами','все клетки B. subtilis в комочке почвы'],['Микробиоценоз','популяции разных микроорганизмов в одном местообитании, связанные взаимодействиями','бактерии, археи, грибы и простейшие в почвенной крошке'],['Экосистема','сообщество вместе с неживой средой и потоками вещества и энергии','озеро, кишечник, участок почвы']])}
 ${K.box('vuz','Определение',`<p><b>Микробиоценоз</b> (microbial community) — совокупность популяций микроорганизмов разных видов, которые населяют один биотоп и связаны прямыми и опосредованными взаимодействиями${R(3,4)}. <b>Биотоп</b> — участок среды с относительно однородными условиями. Для клетки в 1 мкм «однородный» участок может занимать доли миллиметра.</p>`)}
 <p>Чем микробные сообщества отличаются от «больших» экосистем${R(1,5)}: <b>масштаб</b> (градиенты O₂, pH и субстрата на расстоянии микрометров), <b>численность и скорость</b> (сотни миллионов клеток в грамме почвы, удвоение за десятки минут), <b>клональность</b> (соседи по колонии почти идентичны генетически), <b>горизонтальный перенос генов</b>, <b>покой</b> (споры и покоящиеся клетки образуют «банк семян»${R(6)}) и <b>неизвестное большинство</b>: под микроскопом клеток многократно больше, чем колоний на чашке — «аномалия чашечного счёта»${R(7)}. Поэтому сообщества стали описывать по генам, прежде всего 16S рРНК${R(8,9)}.</p>
 <h3 id="k-qs1b">Состав сообщества</h3>
 <p>Видовое богатство S — число видов; относительное обилие pᵢ — доля i-го вида (Σpᵢ = 1); индекс Шеннона H′ = −Σ pᵢ ln pᵢ растёт и с богатством, и с выровненностью; выровненность J = H′/ln S${R(2)}.</p>
 ${K.ex('<p>Четыре вида с долями 0,50; 0,25; 0,15; 0,10: H′ = 0,347 + 0,347 + 0,285 + 0,230 ≈ <b>1,21</b>. Максимум при четырёх видах ln 4 ≈ 1,39, значит J ≈ <b>0,87</b>. Числа учебные.</p>')}
 <p>α-разнообразие описывает один образец, β-разнообразие — различия между образцами. По типу питания (свет или химия, органический или неорганический донор электронов, CO₂ или органика как источник углерода) можно предсказать, кто окажется рядом: E. coli, B. subtilis и C. violaceum — хемоорганогетеротрофы${R(1)}. Клетки сами создают градиенты: в микробной экологии среда — продукт жизнедеятельности сообщества, а не фон.</p>
 <h3 id="k-qs1c">Ниша и принцип Гаузе</h3>
 ${K.box('vuz','Определение',`<p><b>Фундаментальная ниша</b> — область в многомерном пространстве факторов (температура, pH, субстраты, O₂, соль), где популяция может существовать без других видов. <b>Реализованная ниша</b> — её часть, которую вид занимает при конкурентах и хищниках${R(10)}.</p><p><b>Принцип конкурентного исключения (Гаузе)</b>: два вида на одном ограниченном ресурсе в стабильной однородной среде не сосуществуют неограниченно долго${R('14–16')}.</p>`)}
 <p>Конкуренция бывает <b>эксплуатационной</b> (общий ресурс, без прямого контакта) и <b>интерференционной</b> (антибиотики, бактериоцины, токсины через систему секреции VI типа)${R('11–13')}. Парадокс планктона — десятки видов на немногих ресурсах — объясняют непостоянством среды, большим числом ресурсов, пространственной структурой и хищниками, которые не дают победителю разрастись${R(17,2)}.</p>
 <h3 id="k-qs1d">Уравнение Моно и хемостат</h3>
 ${VZ.f('μ = μmax · S / (Ks + S)')}
 <p>Ks — концентрация субстрата, при которой скорость вдвое ниже максимальной${R(18)}. В хемостате свежая среда поступает со скоростью разбавления D, и в стационаре μ = D${R(19)}, откуда остаточная концентрация субстрата:</p>
 ${VZ.f('S* = Ks · D / (μmax − D)')}
 ${F.qsMon.doc}
 <p>Выигрывает вид с меньшим S*: он сводит субстрат ниже уровня, при котором второй вид растёт. Быстрый рост в избытке пищи и умение жить на скудной пище — разные свойства. Отсюда пары r- и K-стратегов, копиотрофов и олиготрофов${R(2)}. Это удобные ярлыки, а не строгая классификация.</p>
 ${K.choice({t:'1. При D = 0,1 ч⁻¹ какой вид из модели выше победит?',opts:['A (μmax = 0,8, Ks = 0,10)','B (μmax = 0,6, Ks = 0,02)','оба сосуществуют','оба вымоются'],ok:[1],a:'<p>S*A = 0,10·0,1/0,7 ≈ 0,014 мМ, S*B = 0,02·0,1/0,5 = 0,004 мМ. Меньше у B — он и побеждает. При медленном протоке выигрывает «олиготроф».</p>'})}
`});

/* ---- 2. Динамика популяций ---- */
VZ.sec('qs',{id:'pop',no:2,t:'Динамика популяций',kw:['логистическ','лотк','вольтерр','эффект олли','банк семян','дрейф'],html:()=>`
 <p class="k-lead">В колбе без подпитки численность проходит лаг, экспоненциальную, стационарную фазу и отмирание${R(1,18)}. В стационарной фазе включаются стрессовые программы, споруляция, вторичные метаболиты и кворум-зависимые ответы.</p>
 ${VZ.f('N(t) = N₀·e^(μt) = N₀·2^(t/g),  g = ln2 / μ')}
 <p>При g = 30 мин за 5 часов проходит 10 генераций, рост в 2¹⁰ = 1024 раза. E. coli в богатой среде удваивается примерно за 20 минут, Mycobacterium tuberculosis — за 18–24 часа${R(1)}.</p>
 <p><b>Логистическая модель</b> dN/dt = r·N·(1 − N/K) вводит предел K (ёмкость среды), но не говорит, чем он задан${R(2)}. <b>Модель Лотки — Вольтерры</b>${R(20)}: каждый вид тормозит другой с коэффициентом α. Устойчивое сосуществование получается, когда каждый вид сильнее тормозит себя, чем конкурента: K₁ < K₂/α₂₁ и K₂ < K₁/α₁₂${R(2)}. В системе «хищник — жертва» численности колеблются, пик хищника запаздывает. Для микробов хищники — простейшие и бактериофаги${R(21)}; фаги действуют по принципу «убей победителя»: чаще заражают самый многочисленный вариант${R(22)}.</p>
 <p><b>Покой и банк семян.</b> Неактивные клетки и споры хранят разнообразие на случай перемен${R(6)}. <b>Эффект Олли</b> — снижение приспособленности при низкой плотности${R(23)}. Для бактерий с кворум-сенсингом у него прямой молекулярный смысл: общественные продукты выгодно делать только при высокой плотности, и опыты показывают приспособленность, зависящую от плотности${R(24)}. <b>Дрейф</b> — случайные колебания в малых популяциях; вместе с отбором, расселением и появлением новых вариантов это четыре базовых процесса теории сообществ${R(25)}.</p>
`});

/* ---- 3. Типы взаимодействий ---- */
VZ.sec('qs',{id:'int',no:3,t:'Типы взаимодействий в сообществе',kw:['мутуализм','комменсализм','аменсализм','перекрёстн','синтрофи','чёрной королев','бактериоцин'],html:()=>`
 ${K.tbl(['Тип','A','B','Пример механизма'],[['Конкуренция','−','−','борьба за общий субстрат'],['Аменсализм','0','−','A выделяет вещество, подавляющее B'],['Хищничество, паразитизм','+','−','простейшее ест бактерию, фаг заражает клетку'],['Комменсализм','+','0','A использует продукты обмена B'],['Мутуализм (синтрофия)','+','+','взаимный обмен метаболитами'],['Нейтрализм','0','0','нет взаимодействия']])}
 ${K.trap(`<p>Знак зависит от условий: антибиотик в высокой концентрации убивает, в очень низкой может служить сигналом, а мутуализм при избытке пищи превращается в конкуренцию. Таблица знаков — первое приближение${R(12,26)}.</p>`)}
 <p><b>Перекрёстное кормление</b> (cross-feeding): продукт одного организма служит субстратом другому${R(27)}. Метаболические зависимости (кому не хватает синтеза аминокислот или витаминов) лучше всего объясняют, какие виды встречаются вместе${R(28)}. Крайний случай — <b>синтрофия</b>: партнёры вместе проводят реакцию, невыгодную каждому по отдельности (раздел 13)${R(29,30)}.</p>
 <p><b>Гипотеза Чёрной Королевы</b>: если функцию «с утечкой» выполняет кто-то за всех, у остальных отбор поддерживает потерю дорогих генов; остаётся немного «помощников»${R(31)}.</p>
 <p><b>Химическая война.</b> Секретируемое оружие — антибиотики и бактериоцины${R(32)}, контактное — система секреции VI типа и контактное ингибирование роста. На агаре три штамма E. coli (продуцент колицина, устойчивый и чувствительный) сосуществуют по принципу «камень, ножницы, бумага», а в перемешиваемой колбе остаётся один${R(33)}. В субингибирующих концентрациях антибиотики меняют транскрипцию у мишеней, отсюда идея об их сигнальной роли; вопрос о главной природной функции открыт${R(34,35)}. Анализ сетей взаимодействий показал, что преобладание конкуренции может стабилизировать сообщество, а обилие кооперации — дестабилизировать: выпадение одного вида тянет за собой цепочку зависимых${R(36)}.</p>
`});

/* ---- 4. Кворум-сенсинг: общая логика ---- */
VZ.sec('qs',{id:'qs',no:4,t:'Кворум-сенсинг: общая логика',sub:[['k-qs4a','История открытия'],['k-qs4b','Цикл и порог'],['k-qs4c','Что измеряет клетка'],['k-qs4d','Классы сигналов']],kw:['кворум','аутоиндуктор','автоиндуктор','diffusion sensing','порог'],html:()=>`
 <h3 id="k-qs4a">История открытия</h3>
 ${K.tbl(['Год','Что произошло'],[['конец 1960-х — 1970','Vibrio fischeri (сейчас Aliivibrio fischeri) светится только в плотной культуре; «отработанная» среда включает свечение в разбавленной. Явление названо автоиндукцией'+R(37)],['1981','установлено строение автоиндуктора: N-(3-оксогексаноил)-L-гомосерин-лактон'+R(38)],['1983','гены свечения перенесены в E. coli, и она засветилась'+R(39)],['1994','предложен термин quorum sensing, описано семейство LuxI/LuxR'+R(40)],['2000-е','такие системы найдены у сотен видов, сигналы разной химии'+R('41–43')]],'k-nostk')}
 ${K.box('vuz','Определение',`<p><b>Кворум-сенсинг</b> (quorum sensing, QS) — регуляция экспрессии генов в ответ на плотность популяции через синтез, выделение и восприятие низкомолекулярных сигналов — автоиндукторов${R(40,41)}.</p>`)}
 <h3 id="k-qs4b">Цикл и порог</h3>
 <p>Каждая клетка понемногу выделяет сигнал. При малой плотности он разбавляется, по мере роста накапливается и, достигнув порога, связывается с рецептором. Комплекс включает целевые гены, среди которых обычно ген синтазы сигнала: положительная обратная связь, автоиндукция.</p>
 ${VZ.f('dA/dt = q·n − δ·A  ⇒  A* = q·n/δ,  nc = δ·Ac/q')}
 <p>q — выработка сигнала одной клеткой, δ — суммарные потери (разрушение, вымывание, диффузия). Пороговая плотность — не константа вида: она растёт с потерями сигнала и падает с его выработкой${R(45,46)}.</p>
 ${F.qsThr.doc}
 <p>Автоиндукция превращает плавное накопление в быстрое переключение, и такие системы могут вести себя как переключатель с двумя устойчивыми состояниями${R(47)}. Резкость у разных систем разная, и клетки одной популяции могут отвечать неодинаково.</p>
 <h3 id="k-qs4c">Что измеряет клетка</h3>
 <p>Клетка измеряет концентрацию сигнала, а на неё влияют и число клеток, и объём, и перемешивание. Отсюда три позиции: классический кворум-сенсинг${R(40)}; <b>диффузионное чувствование</b> — клетка оценивает, удерживается ли сигнал рядом${R(45)}; <b>эффективностное чувствование</b> — оценивает, будет ли работать секретируемый продукт при данной плотности и структуре среды${R(46)}. Несколько сигналов позволяют различить социальную и физическую составляющие окружения${R(48)}, а течение заметно смещает порог${R(49,50)}.</p>
 ${K.trap('<p>«Бактерии считают друг друга» — образное сокращение. Измеряется всегда концентрация сигнала'+R(44)+'.</p>')}
 <h3 id="k-qs4d">Классы сигналов</h3>
 ${K.tbl(['Сигнал','Химия','Кто использует','Особенности'],[['Ацил-гомосерин-лактоны (АГЛ, AHL)','лактонное кольцо + ацильная цепь','многие грамотрицательные','видоспецифичны, рецептор в цитоплазме; разд. 5'],['Аутоиндуцирующие пептиды (AIP)','короткие пептиды, часто модифицированные','грамположительные','мембранная киназа или поглощение; разд. 6'],['AI-2','производные 4,5-дигидрокси-2,3-пентандиона (DPD)','грамположительные и грамотрицательные','синтаза LuxS; разд. 7 и 16'],['DSF','α,β-ненасыщенные жирные кислоты: у Xanthomonas campestris цис-11-метил-2-додеценовая'+R(90)+', у Burkholderia cenocepacia цис-2-додеценовая (BDSF)'+R(171),'Xanthomonas, Burkholderia и др.','система Rpf; разд. 7 и 16'],['Хинолоны (PQS)','2-гептил-3-гидрокси-4-хинолон','Pseudomonas aeruginosa','гидрофобны, переносятся мембранными пузырьками; разд. 5, 7, 16']])}
 ${K.box('tr','Исправление к исходному конспекту',`<p>В исходном PDF сигнал DSF Xanthomonas назван цис-2-додеценовой кислотой. По оригинальной работе это <b>цис-11-метил-2-додеценовая</b> кислота${R(90)}; цис-2-додеценовая кислота — сигнал BDSF Burkholderia cenocepacia${R(171)}. ${OK}</p>`)}
 <p>Обзоры по разным системам: ${R('51–53')}.</p>
`});

/* ---- 5. LuxI/LuxR ---- */
VZ.sec('qs',{id:'lux',no:5,t:'Системы LuxI/LuxR грамотрицательных бактерий',sub:[['k-qs5a','Vibrio fischeri'],['k-qs5b','Химия АГЛ'],['k-qs5c','Рецепторы LuxR'],['k-qs5d','Pseudomonas aeruginosa'],['k-qs5e','Chromobacterium violaceum']],kw:['luxi','luxr','гомосерин','vibrio fischeri','cvir','виолацеин','cv026','lasr','rhlr'],html:()=>`
 <h3 id="k-qs5a">Классическая модель: Vibrio fischeri</h3>
 <p>Морская бактерия живёт в световом органе гавайского кальмара-бобтейла Euprymna scolopes. Партнёрство специфично: орган колонизирует именно V. fischeri${R(54)}. В органе плотность огромная, в открытой воде клеток мало, поэтому свет включается там, где хозяин его использует.</p>
 ${K.tbl(['Ген','Что кодирует'],[['luxI','синтазу автоиндуктора: N-(3-оксогексаноил)-гомосерин-лактон'],['luxR','рецептор и транскрипционный фактор LuxR'],['luxCDABEG','люциферазу (luxAB) и ферменты синтеза её субстрата (luxCDE); разд. 16'+R(172)]])}
 <p>АГЛ свободно проходит через оболочку, и его концентрации снаружи и внутри быстро выравниваются${R(55)}. На пороге АГЛ связывается с LuxR, комплекс садится на lux-бокс перед опероном luxICDABEG и включает и свет, и синтез LuxI: положительная обратная связь${R(40,56)}.</p>
 <h3 id="k-qs5b">Химия АГЛ</h3>
 <p>Постоянная часть — гомосерин-лактоновое кольцо, переменная — ацильная цепь от 4 до ~18 атомов углерода, при C3 водород, оксо- или гидроксигруппа, возможны двойные связи${R(56,57)}. Рецептор различает длину цепи и заместитель при C3, поэтому перекрёстное «прослушивание» ограничено, но возможно${R(58)}.</p>
 <p><b>Синтез.</b> Синтазы LuxI берут кольцо из S-аденозилметионина (SAM), цепь — с ацил-переносящего белка (ацил-АПБ); побочный продукт 5′-метилтиоаденозин. Сигнал тратит SAM и метаболически не бесплатен${R(59)}; подробно — в разделе 16.</p>
 <p><b>Транспорт и стабильность.</b> Короткие АГЛ диффундируют свободно${R(55)}, для 3-оксо-C12-АГЛ P. aeruginosa показан активный выброс${R(60)}. Лактонное кольцо раскрывается в щелочной среде (лактонолиз): быстрее при высоком pH и температуре, медленнее у длинных цепей; при подкислении частично замыкается снова${R(61)}. Ощелачивание старой культуры может само гасить сигнал.</p>
 <h3 id="k-qs5c">Рецепторы семейства LuxR</h3>
 <p>N-концевой домен связывает АГЛ, C-концевой (спираль-поворот-спираль) — ДНК${R(40)}. В структуре TraR из Agrobacterium сигнал полностью спрятан в N-домене, а на ДНК садится димер${R(62)}. Многим белкам семейства сигнал нужен для правильной укладки: без АГЛ они быстро разрушаются${R(56)}. «Одинокие» рецепторы LuxR-solos воспринимают сигналы соседей или иной природы${R(63)}.</p>
 <h3 id="k-qs5d">Иерархия у Pseudomonas aeruginosa</h3>
 ${PH('qs-pa-plate.jpg','Чашка с кровяным агаром, по которой штрихом растут сероватые колонии Pseudomonas aeruginosa','<b>Рис. 5.1.</b> Колонии Pseudomonas aeruginosa на кровяном агаре. Эта бактерия использует сразу три связанных контура кворум-сенсинга.',PHIL(6688,'Dr. Theo. Hawkins'))}
 <p>Las: LasI делает 3-оксо-C12-АГЛ, рецептор LasR${R(65)}; Rhl: RhlI делает C4-АГЛ, рецептор RhlR; Pqs: сигнал PQS${R(66)}. В классической картине Las включает Rhl и Pqs, но иерархия меняется со штаммом и условиями, правильнее говорить о сети${R(64)}. Мутант по lasI образует тонкую недифференцированную биопленку${R(67)}.</p>
 <h3 id="k-qs5e">Chromobacterium violaceum: система CviI/CviR</h3>
 ${PH2(['qs-cv-plate.jpg','Тёмно-фиолетовые колонии Chromobacterium violaceum на чашке с кровяным агаром'],['qs-cv-gram.jpg','Микрофотография мазка, окрашенного по Граму: розовые палочки Chromobacterium violaceum'],`<b>Рис. 5.2.</b> Первый снимок: колонии C. violaceum на кровяном агаре после 24 ч при 37 °C; цвет даёт виолацеин. Второй: та же бактерия в мазке по Граму — грамотрицательные (розовые) палочки.<span class="cr">${PHIL(12434,'Pete Seidel')}. ${PHIL(15881,'Dr. W.A. Clark')}</span>`)}
 <p>Почвенная и водная бактерия тропиков, знаменитая пигментом виолацеином; её система — стандартная модель для изучения АГЛ${R(68,69)}, геном секвенирован${R(70)}. CviI синтезирует АГЛ, CviR — прямой аналог LuxR${R(71)}.</p>
 ${K.box('tr','Какой АГЛ делает C. violaceum',`<p>В работе 1997 года из дикого типа выделили C6-АГЛ (HHL)${R(69)}. В работе 2011 года на типовом штамме ATCC 12472 сообщается, что CviI делает C10-АГЛ, а CviR активируется C10-АГЛ${R(71)}. Причина расхождения (штаммы, условия или методы) в просмотренных источниках не выяснена ${HY}. Вывод: указывайте штамм и ссылку, прежде чем писать, какой АГЛ он производит.</p>`)}
 <p><b>Мишени CviR.</b> Палиндром CTGNCCNNNNGGNCAG; прямо регулируются гены хитиназы, гена, связанного с T6SS, транскрипционного регулятора, гуанин-дезаминазы и самого cviI${R(71)}. В списке прямых мишеней vio-гены не названы, поэтому, напрямую ли CviR включает оперон vioABCDE, пока открыто ${HY}.</p>
 <p><b>Биосенсор CV026.</b> Мутант с транспозоном в cviI не делает пигмент, но фиолетовеет от внешнего АГЛ с цепью C4–C8; АГЛ C10–C14 пигмент не включают, но мешают активирующему АГЛ${R(69)}.</p>
 <p><b>Экология пигмента.</b> Бактерии, производящие виолацеин, токсичны для жгутиковых простейших-бактериофагов${R(75)}: дорогой токсин выгодно делать только при высокой плотности. Но защищает не только пигмент: у родственного вида Chromobacterium piscinae от хищной бактерии Bdellovibrio спасал цианид, а виолацеин в этих опытах за защиту не отвечал${R(182)}.</p>
 <p><b>Виолацеин без АГЛ.</b> Пигмент делают и Janthinobacterium, Duganella. В геноме Janthinobacterium sp. HH01 нет АГЛ-системы и AI-2, зато есть синтаза jqsA, гомологичная CqsA холерного вибриона и LqsA легионеллы, с киназой jqsS и регулятором jqsR; удаление jqsA сильно влияет на синтез виолацеина${R(76)}. У J. lividum виолацеин подавлялся глюкозой и усиливался глицерином${R(77)}. Одинаковый цвет колоний могут давать разные регуляторные механизмы.</p>
 ${K.choice({t:'2. Почему штамм CV026 используют как биосенсор АГЛ?',opts:['он не синтезирует свой АГЛ, но окрашивается в ответ на чужой','он разрушает АГЛ','он светится в присутствии АГЛ','он синтезирует АГЛ всех длин'],ok:[0],a:'<p>Мутация в cviI выключает собственный сигнал, а рецептор CviR остаётся. Внешний АГЛ с короткой цепью включает виолацеин, и колонии становятся фиолетовыми'+R(69)+'.</p>'})}
`});

/* ---- 6. Пептидные системы ---- */
VZ.sec('qs',{id:'pep',no:6,t:'Пептидные системы грамположительных бактерий',kw:['аутоиндуцирующ','agr','comx','phr','rap','двухкомпонентн','гистидин-киназ'],html:()=>`
 <p class="k-lead">У грамположительных сигналами чаще служат пептиды из 5–20 аминокислот, вырезанные из предшественников и нередко модифицированные${R(51,53)}. Пептид сам через оболочку не проходит, поэтому его воспринимают снаружи мембранной гистидин-киназой или затягивают внутрь олигопептидной пермеазой.</p>
 <p><b>Двухкомпонентная система</b>: киназа при связывании лиганда фосфорилирует свой гистидин, затем передаёт фосфат на аспартат регулятора ответа, который садится на ДНК${R(78)}.</p>
 <p><b>Agr у Staphylococcus aureus.</b> Ген agrD кодирует пропептид; AgrB процессирует и выводит его как AIP с циклическим тиолактоном. AIP активирует киназу AgrC, фосфат идёт на AgrA, тот включает регуляторную РНК RNAIII и сам оперон agr. При низкой плотности преобладают белки прикрепления, при высокой — токсины и ферменты${R(79)}.</p>
 <p><b>Bacillus subtilis.</b> Феромон ComX с изопренильной модификацией на триптофане воспринимает киназа ComP, она фосфорилирует ComA, тот ведёт к ComS и компетентности${R('80–82')}. Пятичленный пептид CSF из предшественника PhrC выводится, затем поглощается снова и внутри подавляет фосфатазу RapC: экспортированный пептид работает внутри клетки${R(81,83)}. Пары Rap/Phr встраивают плотность в решение о споруляции${R(84)}.</p>
 ${K.tbl(['Признак','Грамотрицательные (АГЛ)','Грамположительные (пептиды)'],[['Сигнал','липидоподобная молекула','пептид, часто модифицированный'],['Синтез','фермент семейства LuxI','рибосомный предшественник + процессинг'],['Выход','диффузия или эффлюкс','специальные транспортёры'],['Восприятие','цитоплазматический рецептор-фактор транскрипции','мембранная киназа или поглощение'],['Специфичность','видовая, с перекрытием','видовая и штаммовая']])}
 <p>Это общая картина, исключений много, схемы комбинируются${R(52,53)}.</p>
`});

/* ---- 7. AI-2, DSF, PQS, другие каналы, разрушение сигналов ---- */
VZ.sec('qs',{id:'ai2',no:7,t:'AI-2, DSF, PQS, другие каналы и разрушение сигналов',sub:[['k-qs7a','AI-2: общий язык?'],['k-qs7b','Межвидовые и межцарственные сигналы'],['k-qs7c','Контакт, пузырьки, электричество'],['k-qs7d','Quorum quenching']],kw:['ai-2','luxs','dsf','pqs','quorum quenching','лактоназ','ацилаз','aiia','пузырьк','t6ss'],html:()=>`
 <h3 id="k-qs7a">AI-2: общий язык?</h3>
 <p>LuxS образует 4,5-дигидрокси-2,3-пентандион (DPD), который сам превращается в семейство соединений AI-2${R(85,162)}. У V. harveyi активная форма — борсодержащий эфир фуранозы: бор неожиданно нашли в кристалле рецептора${R(86)}; рецептор сальмонеллы узнаёт форму без бора${R(87)}.</p>
 ${K.box('tr','Сигнал везде?',`<p>Ген luxS есть у многих бактерий, а рецепторы AI-2 найдены не у всех. LuxS — часть цикла активированного метила, и у многих видов AI-2 может быть побочным продуктом обмена${R(88,89,163)}. «Универсальный межвидовой язык» — рабочая гипотеза, а не установленный факт.</p>`)}
 <p><b>DSF</b> — α,β-ненасыщенные жирные кислоты системы Rpf; у них есть «межцарственный» аналог: DSF Xanthomonas структурно и функционально сходна с фарнезоевой кислотой гриба Candida albicans и подавляет её переход к нитевидной форме${R(90)}. <b>PQS</b> плохо растворим в воде и переносится мембранными пузырьками${R(91)}.</p>
 <h3 id="k-qs7b">Межвидовые и межцарственные сигналы</h3>
 <p>Многие LuxR-рецепторы отвечают на близкие по строению АГЛ${R(58)}; «правила взаимодействия» видов описаны в${R(92)}. Горох выделяет вещества, которые активируют одни АГЛ-биосенсоры и подавляют другие${R(93)}; кишечные бактерии реагируют на адреналин и норадреналин хозяина${R(94)}.</p>
 <h3 id="k-qs7c">Контакт, пузырьки, электричество</h3>
 <p>Контактное ингибирование роста (CdiA/CdiB у E. coli, иммунный белок защищает своих)${R(95)}; T6SS P. aeruginosa впрыскивает токсин в соседние бактерии${R(96)}; мембранные пузырьки переносят сигналы и есть в матриксе биопленок${R(91,97)}; нанотрубки B. subtilis передают цитоплазматические молекулы и плазмиды${R(98)}; в биопленке B. subtilis волны мембранного потенциала распространяются через калиевые каналы${R(99)}; летучие вещества действуют на расстоянии${R(100)}; клетки Proteus mirabilis на роевой подвижности отличают «своих» и образуют границу с чужими${R(101)}.</p>
 <h3 id="k-qs7d">Разрушение сигналов в природе (quorum quenching)</h3>
 ${K.tbl(['Путь','Что происходит','Пример'],[['Химический распад','лактонное кольцо раскрывается в щелочной среде','ощелачивание старой культуры'+R(61)],['Лактоназа','гидролиз сложноэфирной связи кольца','AiiA бацилл'+R(102)+', металлофермент с цинком'+R(104,105)],['Ацилаза','необратимое расщепление амидной связи','Variovorax paradoxus использует АГЛ как источник C и N'+R(103)]])}
 <p>Зачем это в природе: питание, конкуренция (сломать координацию соседа) и выключение собственного ответа после падения плотности${R(106)}. Концентрация сигнала в сообществе отражает и число продуцентов, и число «разрушителей»: параметр δ из раздела 4 задаёт не только физика, но и биология.</p>
`});

/* ---- 8. Регуляция ---- */
VZ.sec('qs',{id:'reg',no:8,t:'Как сигнал доходит до генов',sub:[['k-qs8a','Инструменты регуляции'],['k-qs8b','Фосфорелей и споруляция'],['k-qs8c','Компетентность и бистабильность'],['k-qs8d','Малые РНК и c-di-GMP']],kw:['оперон','регулон','сигма-фактор','spo0a','фосфорелей','споруляц','компетентн','c-di-gmp','малые рнк','hfq'],html:()=>`
 <h3 id="k-qs8a">Инструменты регуляции</h3>
 <p>У бактерий транскрипция и трансляция идут в одном компартменте и одновременно; РНК-полимеразе нужен сигма-фактор, узнающий промотор${R(1,107)}. <b>Оперон</b> — гены в одной мРНК (lac-оперон Жакоба и Моно${R(108)}, luxICDABEG, vioABCDE); <b>регулон</b> — все гены под одним регулятором, даже разбросанные по хромосоме. LuxR и CviR — активаторы на палиндромных боксах${R(71,107)}. Альтернативные σ переключают полимеразу (σ⁵⁴ у вибрионов, σ споруляции). После транскрипции действуют малые РНК с белком Hfq${R(109)}, стабильность белка, фосфорилирование, вторичные мессенджеры.</p>
 ${K.box('vuz','Что здесь главное','<p>Кворум-сенсинг, споруляция и компетентность собраны из одних деталей: σ-факторов, активаторов, киназ и фосфатаз, малых РНК и мессенджеров. Для новой системы спрашивайте: что воспринимает сигнал, как он передаётся, кто включает гены, есть ли обратная связь.</p>')}
 <h3 id="k-qs8b">Фосфорелей и споруляция B. subtilis</h3>
 ${PH('qs-spores.jpg','Микрофотография: розовые палочки Bacillus в цепочках, внутри многих — изумрудно-зелёные овальные эндоспоры','<b>Рис. 8.1.</b> Эндоспоры Bacillus sp. при окраске малахитовым зелёным (×1000): споры зелёные, вегетативные клетки розовые.',PHIL(1894,'Larry Stauffer, Oregon State Public Health Laboratory'))}
 <p>Эндоспора устойчива к нагреву, высушиванию, радиации и химии${R(1,110)} благодаря малому содержанию воды в ядре, дипиколинату кальция, белкам SASP на ДНК и толстым покровам${R(111)}. Активатор споруляции Spo0A получает фосфат по цепи KinA–E → Spo0F → Spo0B → Spo0A (фосфорелей)${R(112)}: в одной точке складываются голод, повреждения ДНК и плотность. Rap-фосфатазы снимают фосфат с Spo0F, а пептиды Phr их подавляют${R(84)}.</p>
 ${K.seq?K.seq({t:'3. Расставьте этапы споруляции по порядку.',items:['образование кортекса и белковых покровов','асимметричное деление: проспора и материнская клетка','лизис материнской клетки и выход споры','поглощение проспоры материнской клеткой','накопление дипиколината и SASP, обезвоживание ядра'],ok:'24153',a:'<p>Весь путь занимает около 8 часов; его ведёт каскад σ-факторов: σF в проспоре и σE в материнской клетке на ранних этапах, σG и σK позже'+R(110,113)+'.</p>'}):''}
 <p>Низкий уровень Spo0A∼P включает гены матрикса биопленки, для споруляции нужен высокий${R(114)}: одна цепь запускает разные программы в зависимости от «громкости» сигнала.</p>
 <h3 id="k-qs8c">Компетентность и бистабильность</h3>
 <p>Компетентность (способность поглощать внешнюю ДНК) у B. subtilis включает ComK, который поддерживает собственную транскрипцию${R(82)}. Из-за этой петли и шума экспрессии в отдельных клетках${R(115)} компетентной становится только часть популяции${R(47)}: стратегия «не класть все яйца в одну корзину» (bet hedging)${R(116)}.</p>
 <h3 id="k-qs8d">Малые РНК и c-di-GMP</h3>
 <p>Малые РНК спариваются с мРНК и меняют их трансляцию или стабильность, часто с Hfq${R(109)}. Циклический ди-ГМФ синтезируют дигуанилатциклазы (GGDEF), разрушают фосфодиэстеразы (EAL, HD-GYP)${R('117–119')}. Высокий уровень — оседлость и биопленка, низкий — подвижность${R(119)}. У V. cholerae кворум-сенсинг регулирует биопленку через уровень c-di-GMP и репрессию vpsT${R(120)}.</p>
`});

/* ---- 9. Вибрионы и перенос генов ---- */
VZ.sec('qs',{id:'vib',no:9,t:'Полная схема у вибрионов и горизонтальный перенос',kw:['harveyi','luxo','luxu','qrr','hapr','cqsa','трансформац','конъюгац','трансдукц'],html:()=>`
 ${PH('qs-vc-sem.jpg','Сканирующая электронная микрофотография: изогнутые палочки Vibrio cholerae на пористой подложке','<b>Рис. 9.1.</b> Vibrio cholerae серогруппы O1, сканирующая электронная микроскопия (×14 213); две клетки заканчивают деление.',PHIL(7817,'Janice Haney Carr'))}
 <p>У V. harveyi три автоиндуктора: АГЛ-подобный HAI-1, межвидовой AI-2 и CAI-1 (синтаза CqsA); рецепторы LuxN, LuxPQ и CqsS — сенсорные гистидин-киназы${R(41,42)}. Фосфат идёт на LuxU и LuxO${R(121)}; LuxO∼P с σ⁵⁴ включает малые РНК Qrr, которые с Hfq подавляют главный регулятор (LuxR у V. harveyi, HapR у V. cholerae)${R(122,123)}.</p>
 ${F.qsVib.doc}
 ${K.trap('<p>LuxR V. harveyi — главный регулятор кворума, LuxR V. fischeri — рецептор АГЛ. Название одно, белки разные.</p>')}
 <p>Логика инверсии: сигналы выключают киназы, а выключение киназы включает ген. Несколько Qrr работают аддитивно${R(123)}. У V. cholerae при низкой плотности образуется биопленка, а при высокой HapR её подавляет через c-di-GMP${R(120)}.</p>
 <p><b>Горизонтальный перенос.</b> Трансформация (свободная ДНК, компетентность), трансдукция (фаги) и конъюгация (контакт и пиль, обычно плазмида). Конъюгация может контролироваться кворумом: TraR Agrobacterium управляет переносом Ti-плазмиды${R(62)}. Значительная доля генов бактерий приобретена горизонтально${R(124)}, поэтому ниша вида не закреплена его геномом жёстко ${HY}.</p>
`});
})();
